import { CreateDateColumn, PrimaryGeneratedColumn, UpdateDateColumn } from 'typeorm';

/**
 * Base class shared by every entity of the system.
 *
 * It guarantees a single, protected identity model: the columns are private,
 * generated by the database, and can only be read through getters, so no other
 * layer is able to mutate an identifier or a timestamp.
 */
export abstract class BaseEntity {
  @PrimaryGeneratedColumn('uuid', { name: 'id' })
  private _id!: string;

  @CreateDateColumn({ name: 'created_at' })
  private _createdAt!: Date;

  @UpdateDateColumn({ name: 'updated_at' })
  private _updatedAt!: Date;

  get id(): string {
    return this._id;
  }

  get createdAt(): Date {
    return this._createdAt;
  }

  get updatedAt(): Date {
    return this._updatedAt;
  }
}
